import 'package:flutter/foundation.dart';
import 'lifecycle.dart';
import 'kernel_events.dart';
class AiRuntime { final ValueNotifier<KernelLifecycle> lifecycle = ValueNotifier(KernelLifecycle.idle); final ValueNotifier<List<KernelEvent>> events = ValueNotifier([]); Future<void> start() async { lifecycle.value = KernelLifecycle.ready; _emit(KernelEventType.initialized); } Future<T> run<T>(Future<T> Function() task) async { lifecycle.value = KernelLifecycle.processing; try { final result = await task(); return result; } finally { lifecycle.value = KernelLifecycle.ready; } } void _emit(KernelEventType type, [Map<String, dynamic> payload = const {}]) { final list = List<KernelEvent>.from(events.value); list.add(KernelEvent(type: type, payload: payload)); if (list.length > 100) list.removeAt(0); events.value = list; } void emitEvent(KernelEventType type, [Map<String, dynamic> payload = const {}]) { _emit(type, payload); } Future<void> shutdown() async { lifecycle.value = KernelLifecycle.shutdown; _emit(KernelEventType.shutdown); } }
